public class Main {
    public static void main(String[] args) {
        System.out.println("digitSum(4071) = " + digitSum(4071));
        System.out.println("reverse(4071)  = " + reverse(4071));
        System.out.println("factorial(5)   = " + factorial(5));
        System.out.println("isPrime(91)    = " + isPrime(91));
        System.out.println("isPrime(97)    = " + isPrime(97));
    }

    static int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }

    static int reverse(int n) {
        int result = 0;
        while (n > 0) {
            result = result * 10 + n % 10;
            n /= 10;
        }
        return result;
    }

    static int factorial(int n) {
        int product = 1;
        for (int i = 2; i <= n; i++) {
            product *= i;
        }
        return product;
    }

    static boolean isPrime(int n) {
        if (n < 2) {
            return false;       // 0, 1 and negatives are not prime
        }
        for (int i = 2; i < n; i++) {
            if (n % i == 0) {
                return false;   // found a divisor, so stop
            }
        }
        return true;            // nothing divided it
    }
}

