public class Main {
    public static void main(String[] args) {
        printBar(9);
        printBar(0);
        printBar(-4);
    }

    static void printBar(int length) {
        if (length <= 0) {
            System.out.println("(nothing to draw)");
            return;                 // leave now, with no value
        }
        for (int i = 1; i <= length; i++) {
            System.out.print("*");
        }
        System.out.println();
    }
}

